#!/usr/bin/env python3
"""Transcribe the vendored CBOR-LD registry YAML into Rust constants.

Vendor-time tool, not shipped code and not part of the cargo build. It reads
``tables/<id>.yml`` in this directory and writes ``src/registry_tables.rs``
in the crate root, so the codec needs no YAML parser at runtime.

The transcription is checked by ``tests/registry_tables.rs``, which re-parses
the same YAML files with an independent parser and asserts that the generated
constants match, entry for entry.

Usage (from the crate root):

    python3 vendor/cborld-registry/generate_tables.py
    cargo fmt -p cborld-fast-core

The `cargo fmt` step is part of the procedure, not an afterthought: this
script emits one row per line, and rustfmt then settles the final layout.
Running the pair is idempotent, so a re-vendor produces a diff only where the
upstream data actually changed.

Standard library only; no third-party dependency is introduced anywhere.
"""

from __future__ import annotations

import pathlib
import sys

VENDOR = pathlib.Path(__file__).resolve().parent
TABLES = VENDOR / "tables"
OUT = VENDOR.parent.parent / "src" / "registry_tables.rs"

UPSTREAM_COMMIT = "c7ece75bae6ef40c23e19ce111b5c51f3cf38950"


def parse_entry(text: str) -> dict:
    """Parses the registry's YAML subset: scalars, a list of contacts, and
    ``compressionTable`` as a list of ``{type, table}`` mappings."""
    entry: dict = {"compressionTable": []}
    sub: dict | None = None
    section = None
    for raw in text.splitlines():
        if not raw.strip() or raw.strip() == "---":
            continue
        indent = len(raw) - len(raw.lstrip(" "))
        line = raw.strip()
        if indent == 0:
            section = None
            key, _, value = line.partition(":")
            value = value.strip()
            if key == "compressionTable":
                section = "compressionTable"
            elif value:
                entry[key] = value
            else:
                section = key
            continue
        if section != "compressionTable":
            continue  # `contact` list items: recorded in PROVENANCE, not on the wire
        if line.startswith("- type:"):
            sub = {"type": line[len("- type:") :].strip(), "table": []}
            entry["compressionTable"].append(sub)
            continue
        if line == "table:":
            continue
        assert sub is not None, "table row outside a compressionTable entry"
        ident, _, value = line.partition(":")
        sub["table"].append((int(ident.strip()), value.strip()))
    return entry


def rust_str(value: str) -> str:
    escaped = value.replace("\\", "\\\\").replace('"', '\\"')
    return f'"{escaped}"'


def main() -> int:
    ids = sorted(int(path.stem) for path in TABLES.glob("*.yml"))
    entries = {i: parse_entry((TABLES / f"{i}.yml").read_text(encoding="utf-8")) for i in ids}

    out = [
        "// SPDX-License-Identifier: MIT",
        "// Rust guideline compliant 2026-02-21",
        "//! Machine-transcribed CBOR-LD registry entries (generated, do not edit).",
        "//!",
        "//! Generated by `vendor/cborld-registry/generate_tables.py` from the",
        "//! vendored `vendor/cborld-registry/tables/*.yml`, upstream",
        f"//! `json-ld/cborld-registry` at commit `{UPSTREAM_COMMIT}`.",
        "//! See `vendor/cborld-registry/PROVENANCE.md` for the full record and",
        "//! `tests/registry_tables.rs` for the check that this file still",
        "//! matches the vendored YAML byte for byte.",
        "",
        "use crate::registry::{RegistryEntry, SubTable};",
        "",
        "/// Every registry entry vendored from the pinned upstream commit,",
        "/// ascending by identifier.",
        f"pub const REGISTRY_ENTRIES: [RegistryEntry; {len(ids)}] = [",
    ]
    for i in ids:
        entry = entries[i]
        out.append("    RegistryEntry {")
        out.append(f"        id: {i},")
        out.append(f"        domain: {rust_str(entry['domain'])},")
        out.append(f"        mode: {rust_str(entry['mode'])},")
        out.append(f"        provisional: {entry['provisional']},")
        if not entry["compressionTable"]:
            out.append("        sub_tables: &[],")
        else:
            out.append("        sub_tables: &[")
            for sub in entry["compressionTable"]:
                out.append("            SubTable {")
                out.append(f"                table_type: {rust_str(sub['type'])},")
                out.append("                entries: &[")
                for ident, value in sorted(sub["table"]):
                    out.append(f"                    ({ident}, {rust_str(value)}),")
                out.append("                ],")
                out.append("            },")
            out.append("        ],")
        out.append("    },")
    out.append("];")
    out.append("")
    OUT.write_text("\n".join(out), encoding="utf-8")
    print(f"wrote {OUT} ({len(ids)} entries)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
